// Simulación en Node del Constraint Validation API del navegador: se modelan
// campos como objetos planos en vez de elementos `<input>` reales.
function checkValidity(input) {
  const errors = [];
  if (input.required && input.value.trim() === '') errors.push('valueMissing');
  if (input.type === 'email' && input.value && !input.value.includes('@')) errors.push('typeMismatch');
  if (input.minLength && input.value.length < input.minLength) errors.push('tooShort');
  return { valid: errors.length === 0, errors };
}

const emailField = { type: 'email', required: true, value: 'ada@example', minLength: 5 };
const result = checkValidity(emailField);
console.log(result.valid, result.errors.join(',') || '(sin errores)');

const passwordField = { type: 'password', required: true, value: 'abc', minLength: 8 };
const result2 = checkValidity(passwordField);
console.log(result2.valid, result2.errors.join(',') || '(sin errores)');
